import { env as cloudflareEnv } from "cloudflare:workers";

/**
 * The global `Env` comes from `worker-configuration.d.ts`, generated by
 * `wrangler types` from the bindings in wrangler.jsonc. Secrets do not show up
 * there (they are not kept in the config file), so they are declared here.
 */
export type AppEnv = Env & {
  BETTER_AUTH_SECRET: string;
  BETTER_AUTH_URL: string;
  SETUP_SECRET?: string;
  RESEND_API_KEY?: string;
  EMAIL_FROM?: string;
  PUBLIC_TURNSTILE_SITE_KEY?: string;
  TURNSTILE_SECRET_KEY?: string;
  // Social login. Each provider only shows up when its key pair exists.
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
  // Shown in the privacy policy. Public, so they live in `vars`.
  OPERATOR_NAME?: string;
  OPERATOR_CONTACT?: string;
};

/** Social providers actually configured in this environment. */
export function socialProviders(value: AppEnv): Array<"google" | "github"> {
  const list: Array<"google" | "github"> = [];
  if (value.GOOGLE_CLIENT_ID && value.GOOGLE_CLIENT_SECRET) list.push("google");
  if (value.GITHUB_CLIENT_ID && value.GITHUB_CLIENT_SECRET) list.push("github");
  return list;
}

/**
 * The Worker's bindings and secrets. In `astro dev` the Cloudflare plugin runs
 * the code in the real workerd and fills this in from wrangler.jsonc and
 * `.dev.vars` — the same object that exists in production.
 */
export const env = cloudflareEnv as AppEnv;

/**
 * Fails early and loudly if a required secret is not configured — better to
 * break on the first request than to run with weak cryptography.
 */
export function assertEnv(value: AppEnv): asserts value is AppEnv {
  if (!value.BETTER_AUTH_SECRET || value.BETTER_AUTH_SECRET.length < 24) {
    throw new Error(
      "BETTER_AUTH_SECRET is missing or too short. Generate one with `openssl rand -base64 32` " +
        "and put it in .dev.vars (dev) or `wrangler secret put` (production).",
    );
  }
  if (!value.BETTER_AUTH_URL) {
    throw new Error("BETTER_AUTH_URL is missing. E.g. http://localhost:4321 in dev.");
  }
}
